-- Footer navigation (grouped by footer_group; group headings stay translation-driven)

-- Pricing display fields (setup fee, popular badge, per-plan CTA text)
update plans set setup_price_iqd = 75000, popular = false, cta = '{"en": "Get Started", "ar": "ابدأ الآن", "ku": "دەست پێبکە"}'::jsonb where id = 'vee_start';
update plans set setup_price_iqd = 150000, popular = true, cta = '{"en": "Choose Business", "ar": "اختر Business", "ku": "Business هەڵبژێرە"}'::jsonb where id = 'vee_business';
update plans set setup_price_iqd = 300000, popular = false, cta = '{"en": "Choose Pro", "ar": "اختر Pro", "ku": "Pro هەڵبژێرە"}'::jsonb where id = 'vee_pro';
update plans set setup_price_iqd = null, popular = false, cta = '{"en": "Talk to Vee", "ar": "تحدث مع Vee", "ku": "لەگەڵ Vee قسە بکە"}'::jsonb where id = 'vee_custom';

